import{Workspace,writeFile}from'./storage.js';import{extractPDF}from'./pdf.js';import{safeUrl,digest,SECTION_LABELS,fingerprint,reportMarkdown}from'./core.js';import{listModels,analyzePaper,synthesize,generate}from'./analysis.js';import{zip}from'./zip.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let ws=null,professors=[],selected=null,view='library',tab='papers',query='',edit=null,busy=false,controller=null,config={key:'',model:''},models=[],pdfURL='',currentResult=null,renderSeq=0;const content=$('#content');const current=()=>professors.find(p=>p.id===selected);function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',7000)}function link(u,t){return safeUrl(u)?`<a href="${esc(safeUrl(u))}" target="_blank" rel="noopener noreferrer">${esc(t)} ↗</a>`:'<span class="hint">未提供來源連結</span>'}function download(name,data,type='text/plain'){let u=URL.createObjectURL(data instanceof Blob?data:new Blob([data],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function progress(t){$('#jobText').textContent=t}async function job(label,fn){if(busy)return;busy=true;controller=new AbortController();$('#job').hidden=false;progress(label);document.querySelectorAll('.nav,#connect,#refresh').forEach(x=>x.disabled=true);try{await fn(controller.signal);await render()}catch(e){toast(e.message);if(ws){try{professors=await ws.list();await render()}catch{}}}finally{busy=false;$('#job').hidden=true;document.querySelectorAll('.nav,#connect,#refresh').forEach(x=>x.disabled=false);controller=null}}
$('#cancelJob').onclick=()=>controller?.abort();$('#connect').onclick=async()=>{if(!window.showDirectoryPicker){toast('實體資料夾功能需要桌面 Chrome／Edge，請以獨立 HTTPS 頁面開啟。');return}try{let h=await window.showDirectoryPicker({mode:'readwrite',id:'scholar-atlas-v2'});await job('開啟實體資料夾…',async()=>{ws=await Workspace.open(h);professors=await ws.list();selected=null;view='library';$('#folderStatus').textContent=h.name+'/scholar-atlas-data/';$('#connect').textContent='切換資料夾';$('#refresh').hidden=false})}catch(e){if(e.name!=='AbortError')toast('無法開啟資料夾：'+e.message)}};$('#refresh').onclick=()=>job('重新讀取資料…',async()=>{professors=await ws.list();if(!current())selected=null;toast('已重新讀取磁碟資料')});document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>{if(busy)return;view=b.dataset.view;selected=null;render()});$('#closeDialog').onclick=$('#cancel').onclick=()=>{if(!busy)$('#editor').close()};$('#editor').addEventListener('cancel',e=>{if(busy)e.preventDefault()});$('#closeEvidence').onclick=()=>{$('#evidence').close();if(pdfURL)URL.revokeObjectURL(pdfURL);pdfURL=''};
async function render(){let seq=++renderSeq;document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#modelStatus').textContent=config.key&&config.model?'模型已選擇：'+config.model:'模型尚未設定';$('#crumb').textContent=current()?.name||({library:'教授資料夾',model:'分析模型設定',guide:'使用與開發規則'}[view]);if(view==='model')return modelView();if(view==='guide')return guide();if(current())return detail(seq);library()}
function library(){if(!ws){content.innerHTML=`<section class="hero"><div><div class="eyebrow">START WITH YOUR OWN PAPERS</div><h1>研究資料，真正留在你的資料夾。</h1><p>建立教授目錄，讀取論文原文，讓研究概要附上可核對的頁碼。</p></div></section><div class="panel welcome"><div class="folder-art">▱</div><h2>選一個資料夾，開始建立研究庫</h2><p>系統會在你選擇的位置建立 <b>scholar-atlas-data</b>，<br>每位教授都有自己的資料夾，保存 PDF、逐頁文字與分析。</p><button class="primary" data-act="connect">選取電腦資料夾</button><p class="hint">需要桌面 Chrome／Edge；請直接開啟網站，不要在嵌入預覽中使用。<br>沒有範例資料。既有 v1 瀏覽器資料不會被刪除，也不會自動匯入。</p></div><div class="steps"><div><b>01　建立教授目錄</b><p>教授資料與論文來源寫入磁碟。</p></div><div><b>02　讀取 PDF 原文</b><p>逐頁擷取文字，保留 PDF 實際頁次。</p></div><div><b>03　分析與回查</b><p>模型分析後，核對引文並回到原頁。</p></div></div>`;return}let total=professors.reduce((a,p)=>a+p.papers.length,0),done=professors.reduce((a,p)=>a+p.papers.filter(q=>q.analysisAt).length,0);content.innerHTML=`<section class="hero"><div><div class="eyebrow">YOUR RESEARCH LIBRARY</div><h1>教授與原文資料庫</h1><p>資料直接保存在你的電腦；模型分析只在你按下按鈕並同意後執行。</p></div><button class="primary" data-act="add-prof">＋ 新增教授</button></section><div class="stats"><div class="stat"><div class="stat-icon">▱</div><div><strong>${professors.length}</strong><small>實體教授目錄</small></div></div><div class="stat"><div class="stat-icon">▤</div><div><strong>${total}</strong><small>論文與來源</small></div></div><div class="stat"><div class="stat-icon">✓</div><div><strong>${done}</strong><small>已完成原文分析</small></div></div></div><div class="toolbar"><input id="search" aria-label="搜尋教授" placeholder="搜尋教授、學校、Program" value="${esc(query)}"></div><div class="grid" id="cards"></div><section class="panel"><h3>我的申請研究方向</h3><p>跨論文分析會依這段內容說明關聯與可能的研究問題。</p><textarea id="interests" aria-label="申請研究方向" placeholder="例如：結合運籌最佳化與機器學習，研究受限制的決策問題。">${esc(ws.settings.interests)}</textarea><button style="margin-top:12px" data-act="save-interests">儲存研究方向</button></section>`;cards();$('#search').oninput=e=>{query=e.target.value;cards()}}
function cards(){$('#cards').innerHTML=professors.filter(p=>[p.name,p.school,p.program].join(' ').toLowerCase().includes(query.toLowerCase())).map(p=>`<article class="card"><div class="card-top"><div class="avatar">${esc(p.name.slice(0,2))}</div><span class="badge green">磁碟目錄</span></div><h2>${esc(p.name)}</h2><div class="school">${esc(p.school)} · ${esc(p.program)}</div><p>${p.papers.filter(q=>q.hasPDF).length} 份原文 PDF<br>${p.papers.filter(q=>q.analysisAt).length} 篇有可回查的分析</p><div class="card-bottom"><span>▤ ${p.papers.length} 篇論文</span><button data-act="open" data-id="${esc(p.id)}">開啟資料夾 →</button></div></article>`).join('')+`<button class="card add-card" data-act="add-prof"><span class="plus">＋</span><h3>新增一位教授</h3><p>不預填研究方向或論文<br>從你的原始資料開始</p></button>`}
async function detail(seq){let p=current();content.innerHTML=`<section class="hero"><div><div class="eyebrow"><a href="#" data-act="back">← 教授資料夾</a></div><h1>${esc(p.name)}</h1><p>${esc(p.school)} · ${esc(p.program)}　${link(p.url,'官方頁面')}</p><small class="hint">professors/${esc(p.folder)}/</small></div><div class="actions"><button data-act="edit-prof">編輯教授</button><button data-act="zip">↓ 匯出完整資料夾</button><button class="primary" data-act="add-paper">＋ 新增論文</button></div></section><div class="tabs">${[['papers','論文原文'],['synthesis','跨論文概要'],['notes','申請筆記']].map(([k,n])=>`<button data-act="tab" data-id="${k}" class="${tab===k?'selected':''}">${n}</button>`).join('')}</div><div id="detailBody"></div>`;let d=$('#detailBody');if(tab==='papers'){d.innerHTML=`<div class="panel"><h2>論文與原文分析</h2>${[...p.papers].sort((a,b)=>(b.year||0)-(a.year||0)).map(q=>`<article class="paper"><div class="year">${esc(q.year||'未填')}</div><div><h3>${esc(q.title)}</h3><span class="badge ${q.analysisAt?'green':''}">${q.analysisAt?'已分析 · '+q.analysisCount+' 條主張':q.hasPDF?'已讀取 '+q.pageCount+' 頁':'僅來源連結'}</span><p>${q.hasPDF?`PDF：${esc(q.originalName)}${q.lowPages?.length?' · '+q.lowPages.length+' 頁文字稀少':''}`:'尚未提供原文，不能進行原文分析。'}</p>${link(q.url,'論文來源')}<p class="hint">ID：${esc(q.id)}</p></div><div class="actions paper-actions"><button data-act="edit-paper" data-id="${esc(q.id)}">資料／附加原文</button>${q.hasPDF?`<button data-act="read" data-id="${esc(q.id)}">閱讀 PDF 與文字</button><button class="primary" data-act="analyze" data-id="${esc(q.id)}">${q.analysisAt?'重新分析':'分析原文'}</button>`:''}${q.analysisAt?`<button data-act="analysis" data-id="${esc(q.id)}">查看分析與引用</button>`:''}<button class="danger" data-act="archive-paper" data-id="${esc(q.id)}">移到封存</button></div></article>`).join('')||'<div class="empty">尚未加入論文。新增資料時可附上有權使用的 PDF，或先保存來源連結。</div>'}</div><p class="hint">圖表與圖片不會被文字擷取完整讀取。掃描 PDF 需先 OCR；任何分析都會標示文字缺口。</p><button class="danger" data-act="archive-prof">封存教授資料夾</button>`}else if(tab==='notes'){d.innerHTML=`<div class="panel"><h2>我的申請筆記</h2><p>記錄你確實閱讀的內容、研究經驗與想向教授提問的問題。此欄為你的筆記，不會冒稱為模型分析。</p><textarea id="notes" style="min-height:300px" aria-label="申請筆記">${esc(p.notes||'')}</textarea><button class="primary" data-act="save-notes">儲存筆記</button></div>`}else{d.innerHTML='<div class="panel">讀取已儲存概要…</div>';let result=await ws.synthesis(p);if(seq!==renderSeq)return;currentResult=result;let available=p.papers.filter(q=>q.analysisAt);d.innerHTML=`<div class="panel"><h2>跨論文研究分析</h2><p>以已完成原文分析的論文為材料，歸納主軸、研究演進、共同方法與申請方向關聯。每條結論保留可回查的原文引用。</p><p class="hint">申請方向：${esc(ws.settings.interests||'尚未設定，可回教授資料夾首頁填寫。')}</p><div class="selection">${available.map(q=>`<label><input type="checkbox" name="selectedPaper" value="${esc(q.id)}" checked> ${esc(q.title)} (${q.year||'年份未填'})</label>`).join('')||'<p>請先完成至少兩篇論文的原文分析。</p>'}</div><button class="primary" data-act="synthesize" ${available.length<2?'disabled':''}>分析所選論文</button></div>${result?`${result.fingerprint!==fingerprint(p,ws.settings.interests)?'<div class="notice warning">資料或申請方向已更新；以下是先前保存的概要，請重新分析。</div>':''}<div class="actions"><button data-act="download-synthesis">↓ 下載概要 Markdown</button></div>${reportHTML(result,p.papers)}`:''}`}}
function reportHTML(r,papers){return `<div class="notice"><b>來源可回查，不代表結論已人工驗證。</b><br>模型：${esc(r.model)} · ${esc(new Date(r.createdAt).toLocaleString('zh-TW',{timeZone:'Asia/Taipei'}))}<br>${esc(r.coverage)}<br>引文核對未通過而排除的主張：${r.rejected?.length||0}</div>`+Object.entries(SECTION_LABELS).map(([k,n])=>{let claims=r.claims.filter(c=>c.section===k);return claims.length?`<section class="panel"><h2>${n}</h2>${claims.map(c=>`<div class="claim"><span class="badge ${c.kind==='evidence'?'green':''}">${c.kind==='evidence'?'依原文整理':'推論／建議'}</span><p>${esc(c.text)}</p><div class="citations">${c.citations.map(ref=>`<button data-act="cite" data-id="${esc(ref.paperId)}" data-page="${ref.page}" data-quote="${esc(ref.quote)}">${esc(papers.find(q=>q.id===ref.paperId)?.title||ref.paperId)} · PDF p.${ref.page} ↗</button>`).join('')}</div></div>`).join('')}</section>`:''}).join('')+`<div class="panel"><h3>涵蓋範圍與限制</h3><p class="pre">${esc(r.gaps||'未另列')}</p><p class="hint">頁碼為 PDF 檔案實際頁次，不一定等於論文印刷頁碼；圖表、公式與雙欄排版可能影響文字完整性。</p></div>`}
function modelView(){content.innerHTML=`<section class="hero"><div><div class="eyebrow">REAL MODEL CONNECTION</div><h1>連接你的分析模型</h1><p>直接使用你的 Gemini API。沒有內建金鑰，也不以模板替代分析。</p></div></section><section class="panel"><h2>Gemini API 設定</h2><p>金鑰只保存在此分頁記憶體，重新整理後需重填；不會寫入磁碟、GitHub 或網站伺服器。模型呼叫依你的 API 方案計費／限額。<br>只有在分析確認後，論文擷取文字、引用與研究興趣才會送至 Google Gemini。</p><p>${link('https://aistudio.google.com/apikey','在 Google AI Studio 取得 API 金鑰')}</p><label class="field">API Key<input id="apiKey" type="password" autocomplete="off" placeholder="輸入你自己的 Gemini API key"></label><div class="actions" style="margin-top:14px"><button data-act="verify-key" class="primary">驗證金鑰並取得模型</button><button data-act="clear-key">清除本分頁金鑰</button></div><p class="hint">${config.key?'此分頁已保留驗證過的金鑰；空白輸入框不代表金鑰已清除。':'尚未設定金鑰。請勿把金鑰貼進聊天或提交到 Repository。'}</p>${models.length?`<label class="field">可用的文字生成模型<select id="modelSelect">${models.map(m=>`<option ${config.model===m?'selected':''}>${esc(m)}</option>`).join('')}</select></label><button data-act="test-model" style="margin-top:14px">測試一次生成連線</button><p class="hint">測試只送出一小段連線測試文字，不包含研究資料；會產生一次 API 呼叫。</p>`:''}</section>`;if($('#modelSelect'))$('#modelSelect').onchange=e=>{config.model=e.target.value;$('#modelStatus').textContent='模型已選擇：'+config.model}}
function guide(){content.innerHTML=`<section class="hero"><div><div class="eyebrow">A VERIFIABLE WORKFLOW</div><h1>從原文到研究概要</h1><p>沒有預填教授、示範論文或模擬分析結果。</p></div></section><div class="panel"><h2>使用順序</h2><ol><li>用桌面 Chrome／Edge 開啟網站，選取電腦上的資料夾。</li><li>新增教授並加入論文。來源連結不會自動下載；請上傳有權使用的 PDF。</li><li>系統以 PDF.js 在本機逐頁擷取文字，保存 original.pdf 與 pages.json。</li><li>在模型設定輸入自己的 Gemini API key，選擇模型並測試連線。</li><li>按「分析原文」，確認傳送範圍；完成後查看問題、方法、成果、限制與引用。</li><li>按引用按鈕，回查 PDF 對應頁與擷取文字。</li><li>至少兩篇分析完成後，選取論文產生跨論文概要。</li></ol></div><div class="panel"><h2>你的資料存在哪裡？</h2><p class="pre">scholar-atlas-data/workspace.json：申請研究方向\nprofessors/教授姓名-ID/profile.json：教授資料與論文清單\nprofessors/教授姓名-ID/papers/論文ID/original.pdf：原文\n同一論文目錄/pages.json：逐頁擷取文字\n同一論文目錄/analysis.json、analysis.md：附引用分析\n教授目錄/synthesis.json、synthesis.md：跨論文概要\n教授目錄/application-notes.md：申請筆記（儲存筆記後建立）\ntrash/：封存資料，可在電腦檔案總管取回</p><p>每次重新開啟網站需重新選取相同父資料夾。不使用 v1 的瀏覽器假資料。資料夾匯出 ZIP 會包含實際檔案。</p></div><div class="panel"><h2>明確限制</h2><p>不支援自動全網搜尋、付費論文繞過、掃描 PDF OCR 或圖表視覺理解。無文字頁面會標示缺口。API 中斷、引用核對失敗與輸出截斷均不會顯示完成。片段核對證明引文存在，不證明論述或推論正確。</p></div><div class="panel"><h2>作業與開發文件</h2><div class="doclinks"><a href="AGENTS.md" download>AGENTS.md ↓</a><a href="README.md" download>README ↓</a><a href="SUBMISSION.md" download>繳交說明 ↓</a><a href="scholar-atlas-source.zip" download>完整原始碼 ZIP ↓</a></div></div>`}
const input=(n,l,v='',t='text',required=false)=>`<label class="field">${l}<input name="${n}" type="${t}" value="${esc(v)}" ${required?'required':''} ${t==='number'?'min="1900" max="2200"':''}></label>`;
function editor(kind,x={}){if(!ws){toast('請先選取電腦資料夾');return}edit={kind,id:x.id};$('#dialogTitle').textContent=(x.id?'編輯':'新增')+(kind==='prof'?'教授資料':'論文與原文');$('#fields').innerHTML=kind==='prof'?input('name','教授姓名 *',x.name,'text',true)+input('school','學校',x.school)+input('program','Program／系所',x.program)+input('url','官方研究頁面',x.url,'url'):input('title','論文標題 *',x.title,'text',true)+input('year','所收錄版本的發表年份（可留空）',x.year||'','number')+input('url','原始論文／DOI 來源連結',x.url,'url')+`<label class="field">原文 PDF（50 MB 以下；掃描檔需先 OCR）<input name="pdf" type="file" accept=".pdf,application/pdf" ${x.hasPDF?'disabled':''}></label>${x.hasPDF?'<p class="hint">已保存原文。若要替換為不同版本，請新增一筆論文，以免破壞既有引用。</p>':''}<label class="check"><input name="authorship" type="checkbox" required ${x.authorship?'checked':''}>我已確認這位教授是論文作者之一，且有權保存所附 PDF。</label><p class="hint">只填來源連結也可保存，但沒有 PDF 就不能執行原文分析。</p>`;$('#editor').showModal()}
$('#editForm').onsubmit=async e=>{e.preventDefault();if(busy)return;let f=new FormData(e.target),p=current(),meta={};for(let k of edit.kind==='prof'?['name','school','program','url']:['title','url'])meta[k]=String(f.get(k)||'').trim();if(meta.url&&!safeUrl(meta.url)){toast('網址須為 HTTP／HTTPS');return}if(edit.kind==='prof'&&!meta.name||edit.kind==='paper'&&!meta.title){toast('請填寫必要欄位');return}if(edit.kind==='paper'){meta.year=f.get('year')?Number(f.get('year')):null;if(meta.year!==null&&(!Number.isInteger(meta.year)||meta.year<1900||meta.year>2200)){toast('年份無效');return}meta.authorship=f.get('authorship')==='on';if(!meta.authorship){toast('請確認作者與檔案使用權');return}if(p.papers.some(q=>q.id!==edit.id&&(q.title.toLowerCase()===meta.title.toLowerCase()||(meta.url&&q.url===meta.url)))){toast('此標題或來源連結已收錄');return}}await job('儲存資料…',async signal=>{if(edit.kind==='prof'){if(edit.id){Object.assign(p,meta);await ws.saveProfessor(p)}else{let added=await ws.addProfessor({...meta,notes:''});professors.push(added);selected=added.id;tab='papers'}}else{let old=p.papers.find(q=>q.id===edit.id),q={...old,...meta,id:edit.id||crypto.randomUUID(),hasPDF:old?.hasPDF||false},file=f.get('pdf'),pages=null;if(file?.size&&!old?.hasPDF){pages=await extractPDF(file,(n,total)=>progress(`擷取 PDF 第 ${n} / ${total} 頁`),signal);q.hash=await digest(await file.arrayBuffer());q.textHash=await digest(JSON.stringify(pages));if(p.papers.some(x=>x.id!==q.id&&x.hash===q.hash))throw Error('此 PDF 已收錄在同一位教授的資料夾');q.hasPDF=true;q.originalName=file.name;q.pageCount=pages.length;q.lowPages=pages.filter(x=>x.text.trim().length<30).map(x=>x.page);q.status='extracted'}if(!q.hasPDF&&!q.url)throw Error('請提供 PDF 或論文來源連結');if(signal.aborted)throw Error('已取消，未建立論文');if(old){if(file?.size&&!old.hasPDF){let dir=await ws.paperDir(p,q);await writeFile(dir,'original.pdf',file);await writeFile(dir,'pages.json',JSON.stringify(pages,null,2))}Object.assign(old,q);await ws.savePaper(p,old)}else await ws.addPaper(p,q,file?.size?file:null,pages)}$('#editor').close();toast('已寫入實體資料夾')})};
async function evidence(p,q,page=1,quote=''){let pages=await ws.pages(p,q);if(!Number.isInteger(page)||page<1||page>pages.length)throw Error('引用頁碼不在 PDF 範圍內');if(pdfURL)URL.revokeObjectURL(pdfURL);pdfURL=URL.createObjectURL(await ws.pdf(p,q));$('#evidenceTitle').textContent=q.title;$('#evidenceBody').innerHTML=`<div class="toolbar"><label>PDF 頁次 <select id="pageSelect">${pages.map(pg=>`<option value="${pg.page}" ${pg.page===page?'selected':''}>${pg.page} / ${pages.length}${pg.label!==String(pg.page)?'（標籤 '+esc(pg.label)+'）':''}</option>`).join('')}</select></label><a href="${pdfURL}" download="${esc(q.originalName)}">下載原始 PDF</a></div>${quote?`<blockquote>${esc(quote)}</blockquote><p class="hint">上方引文已在該頁擷取文字中核對；請閱讀上下文判斷結論是否成立。</p>`:''}<div class="evidence-grid"><iframe id="pdfFrame" title="PDF 原文" src="${pdfURL}#page=${page}"></iframe><div><h3>該頁擷取文字</h3><pre id="pageText">${esc(pages[page-1].text||'此頁沒有可擷取文字，需要先 OCR。')}</pre></div></div>`;$('#pageSelect').onchange=e=>{let n=Number(e.target.value);$('#pdfFrame').src=pdfURL+'#page='+n;$('#pageText').textContent=pages[n-1].text||'此頁沒有可擷取文字，需要先 OCR。'};$('#evidence').showModal()}
async function exportFolder(p){let entries=[];async function walk(dir,path){for await(let[n,h]of dir.entries()){if(h.kind==='directory')await walk(h,path+'/'+n);else entries.push([path+'/'+n,await h.getFile()])}}await walk(await ws.profDir(p),p.folder);download(p.folder+'.zip',await zip(entries));toast('已匯出磁碟中的完整教授資料夾')}
function requireModel(){if(!config.key||!config.model){toast('請先到「分析模型設定」驗證金鑰並選擇模型');return false}return true}
document.addEventListener('click',async e=>{let b=e.target.closest('[data-act]');if(!b)return;e.preventDefault();if(busy){toast('目前正在處理，請等待或取消');return}let a=b.dataset.act,k=b.dataset.id,p=current(),q=p?.papers.find(x=>x.id===k);try{if(a==='connect')$('#connect').click();if(a==='add-prof')editor('prof');if(a==='edit-prof')editor('prof',p);if(a==='open'){selected=k;tab='papers';await render()}if(a==='back'){selected=null;await render()}if(a==='tab'){tab=k;await render()}if(a==='add-paper')editor('paper');if(a==='edit-paper')editor('paper',q);if(a==='read'||a==='cite')await evidence(p,q,Number(b.dataset.page||1),b.dataset.quote||'');if(a==='save-interests'){ws.settings.interests=$('#interests').value;await ws.saveSettings();toast('研究方向已儲存；舊概要會標示需要重新分析')}if(a==='save-notes'){p.notes=$('#notes').value;await ws.saveProfessor(p);await writeFile(await ws.profDir(p),'application-notes.md',p.notes);toast('已儲存申請筆記')}if(a==='zip')await job('打包實體資料夾…',()=>exportFolder(p));if(a==='archive-paper'||a==='archive-prof'){if(confirm('將資料移至工作區的 trash 封存目錄？原始檔仍會保留在電腦，可自行取回。'))await job('封存資料…',async()=>{await ws.archive(p,a==='archive-paper'?q:null);professors=await ws.list();if(a==='archive-prof')selected=null})}if(a==='verify-key'){let key=$('#apiKey').value.trim()||config.key;if(!key)throw Error('請輸入 API key');await job('向 Gemini 驗證金鑰並查詢模型…',async signal=>{let found=await listModels(key,signal);models=found.filter(m=>!/(image|audio|tts|robotics)/i.test(m));if(!models.length)throw Error('此金鑰沒有可用的文字生成模型');config={key,model:models.find(m=>/flash/.test(m))||models[0]};toast('金鑰可讀取模型列表；可再測試一次生成連線')})}if(a==='clear-key'){config={key:'',model:''};models=[];render();toast('已清除本分頁金鑰')}if(a==='test-model'){if(!requireModel())return;await job('測試真實模型生成…',async signal=>{await generate(config,'這是連線測試。回傳 JSON：claims 為空陣列，gaps 為「連線成功」。',signal);toast('模型生成連線成功')})}if(a==='analyze'){if(!requireModel())return;await ws.pdf(p,q);let pages=await ws.pages(p,q),n=pages.filter(x=>x.text.trim()).length;if(!n)throw Error('這份 PDF 沒有可擷取文字，請先 OCR');if(!confirm(`將「${q.title}」共 ${pages.length} 頁的擷取文字送至 Google Gemini（${config.model}）分析，使用你的 API 額度。圖像本身不會送出。繼續？`))return;await job('準備原文分析…',async signal=>{let result=await analyzePaper({...config},q,pages,progress,signal);if(signal.aborted)throw Error('已取消，未覆寫分析');await ws.saveAnalysis(p,q,result,reportMarkdown(q.title,result,p.papers));toast('原文分析已儲存；請查看引用並核對語意')})}if(a==='analysis'){let result=await ws.analysis(p,q);if(!result)throw Error('找不到 analysis.json，請重新分析');currentResult=result;content.innerHTML=`<section class="hero"><div><div class="eyebrow"><a href="#" data-act="return-detail">← 返回論文</a></div><h1>${esc(q.title)}</h1><p>原文分析 · 引用片段已核對，推論仍需人工判斷</p></div><button data-act="download-analysis" data-id="${esc(q.id)}">↓ 下載分析</button></section>${reportHTML(result,p.papers)}`;}if(a==='return-detail')await render();if(a==='download-analysis'){let r=await ws.analysis(p,q);download(q.id+'-analysis.md',reportMarkdown(q.title,r,p.papers))}if(a==='download-synthesis'){let r=await ws.synthesis(p);download(p.name+'-synthesis.md',reportMarkdown(p.name+' 研究概要',r,p.papers))}if(a==='synthesize'){if(!requireModel())return;let ids=[...document.querySelectorAll('input[name="selectedPaper"]:checked')].map(x=>x.value);if(ids.length<2)throw Error('請至少選取兩篇已分析論文');if(ids.length>20)throw Error('每次最多選取 20 篇，避免超過模型上下文');if(!confirm(`將 ${ids.length} 篇論文的分析與原文引文，以及你的申請研究方向送至 Google Gemini，使用 API 額度。繼續？`))return;await job('載入已分析原文證據…',async signal=>{let docs=[];for(let id of ids){let paper=p.papers.find(x=>x.id===id),analysis=await ws.analysis(p,paper);if(!analysis||analysis.pdfHash!==paper.hash)throw Error('部分論文分析缺失或版本不符，請先重新分析');await ws.pdf(p,paper);docs.push({...paper,pages:await ws.pages(p,paper),analysis})}let result=await synthesize({...config},p,docs,ws.settings.interests,progress,signal);if(signal.aborted)throw Error('已取消，未覆寫概要');await ws.saveSynthesis(p,result,reportMarkdown(p.name+' 研究概要',result,p.papers));toast('跨論文概要已寫入教授資料夾')})}}catch(e){toast(e.message)}});render();
